// lookup demo — Diamond (jahdb demo program)
var DATA={"Diamond":"Diamond is pure carbon, the hardest natural material and the April birthstone. Cut brilliance comes from its unmatched refractive index."};
function lookup(q){q=String(q).toLowerCase();var h=[];for(var k in DATA){if((k+" "+DATA[k]).toLowerCase().indexOf(q)>=0)h.push(k+": "+DATA[k]);}return h.length?h.join("\n"):"no match for "+q;}
function listAll(){return Object.keys(DATA).join(", ");}
console.log("sample lookup:");console.log(lookup("10"));

